<?php require __DIR__.'/../includes/bootstrap.php';require_auth();if(!artist_alley_ready())redirect('upgrade-artist-alley.php');
$existing=artist_for_user((int)user()['id']);if($existing)redirect_route('artist-alley/manage.php',['id'=>$existing['id'],'tab'=>'profile']);
$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$name=trim($_POST['artist_name']??'');if($name==='')throw new RuntimeException('Artist name is required.');$slug=artist_slug($name);$avatar=save_uploaded_image('avatar','artists/avatars',(int)user()['id']);$banner=save_uploaded_image('banner','artists/banners',(int)user()['id']);db()->prepare("INSERT INTO artist_profiles(user_id,slug,artist_name,headline,bio,specialties,website,commission_status,status,avatar_path,banner_path) VALUES(?,?,?,?,?,?,?,?,?,?,?)")->execute([user()['id'],$slug,$name,trim($_POST['headline']??''),trim($_POST['bio']??''),trim($_POST['specialties']??''),trim($_POST['website']??''),$_POST['commission_status']??'closed',(user()['role']==='admin'?'approved':'pending'),$avatar,$banner]);flash('success','Artist profile created.');redirect_route('artist-alley/manage.php',['id'=>(int)db()->lastInsertId()]);}catch(Throwable $e){$error=$e->getMessage();}}
app_header('Create Artist Profile');?>
<section class="form-card wide"><p class="eyebrow">ARTIST ALLEY</p><h1>Create Artist Profile</h1><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif?><form method="post" enctype="multipart/form-data" class="form-grid"><?=csrf_field()?><label>Artist or studio name<input name="artist_name" required></label><label>Headline<input name="headline" placeholder="Comic artist, illustrator, prop maker..."></label><label class="full">Biography<textarea name="bio" rows="7"></textarea></label><label class="full">Specialties<input name="specialties" placeholder="Sequential art, character design, watercolor"></label><label>Website<input name="website" type="url"></label><label>Commission status<select name="commission_status"><option value="closed">Closed</option><option value="open">Open</option><option value="waitlist">Waitlist</option></select></label><label>Avatar<input type="file" name="avatar" accept="image/*"></label><label>Banner<input type="file" name="banner" accept="image/*"></label><div class="full"><button class="button primary">Create Artist Profile</button></div></form></section><?php app_footer();
